// Un servidor que atiende cuatro peticiones y no cuenta ninguna.
// Paso 1: una línea de log por petición, con lo que respondió.

const http = require('http');
const { buscarPedidos } = require('./pedidos');
const { log } = require('./log');

function atender(peticion, respuesta) {
  if (peticion.url === '/api/pedidos') {
    const pedidos = buscarPedidos();
    respuesta.end(JSON.stringify(pedidos));
    return;
  }

  if (peticion.url === '/') {
    respuesta.end('Hola');
    return;
  }

  respuesta.statusCode = 404;
  respuesta.end('No encontrado');
}

const servidor = http.createServer(function (peticion, respuesta) {
  atender(peticion, respuesta);
});

servidor.listen(3000);

// La capa de datos. Deja su línea de log, pero no sabe nada de la
// petición que la llamó: cuando hay tráfico, esa línea no se puede
// atribuir a nadie.

const { log } = require('./log');

function buscarPedidos() {
  const pedidos = [{ id: 'A-1042' }, { id: 'A-1043' }];

  log('info', 'consulta_pedidos', { encontrados: pedidos.length });

  return pedidos;
}

module.exports = { buscarPedidos };

// El logger de la lección anterior, tal cual. Aquí ya no se toca.

function log(level, event, datos) {
  console.log(
    JSON.stringify({
      ts: new Date().toISOString(),
      service: 'pedidos-api',
      level: level,
      event: event,
      ...datos,
    }),
  );
}

module.exports = { log };

