const http = require('http');
const { buscarPedidos } = require('./pedidos');
const { log } = require('./log');

let atendidas = 0;

function atender(peticion, respuesta, requestId) {
  if (peticion.url === '/api/pedidos') {
    const pedidos = buscarPedidos(requestId);
    respuesta.end(JSON.stringify(pedidos));
    return;
  }

  if (peticion.url === '/') {
    respuesta.end('Hola');
    return;
  }

  respuesta.statusCode = 404;
  respuesta.end('No encontrado');
}

const servidor = http.createServer(function (peticion, respuesta) {
  atendidas += 1;
  const requestId = 'req-' + atendidas;

  atender(peticion, respuesta, requestId);

  log('info', 'http_request', {
    requestId: requestId,
    method: peticion.method,
    url: peticion.url,
    status: respuesta.statusCode,
  });
});

servidor.listen(3000);

const { log } = require('./log');

function buscarPedidos(requestId) {
  const pedidos = [{ id: 'A-1042' }, { id: 'A-1043' }];

  log('info', 'consulta_pedidos', {
    requestId: requestId,
    encontrados: pedidos.length,
  });

  return pedidos;
}

module.exports = { buscarPedidos };

